import * as T from './vendor/three.js';
export function createViewArms(){const group=new T.Group(),material=new T.MeshStandardMaterial({color:'#66b9df',roughness:.8,flatShading:true});for(const side of[-1,1]){const arm=new T.Group();arm.position.set(side*.24,-.28,-.4);arm.rotation.z=side*-.16;const forearm=new T.Mesh(new T.CylinderGeometry(.05,.065,.31,6),material);forearm.rotation.x=Math.PI/2;arm.add(forearm);const hand=new T.Mesh(new T.IcosahedronGeometry(.065,0),material);hand.position.z=-.18;arm.add(hand);group.add(arm)}group.userData.animate=(time,moving)=>{group.position.y=moving?Math.sin(time*12)*.013:0};return group}
